    def loads_unsafe(self, signed_payload: _TSerialized) -> tuple[bool, t.Any]:
        """Loads a signed payload without verifying the signature. Returns a
        tuple of ``(valid, payload)`` where ``valid`` indicates if the signature
        was valid and ``payload`` is the deserialized object if the signature
        was valid, otherwise ``None``.
        """
        if isinstance(signed_payload, str):
            signed_payload = signed_payload.encode("utf-8")
        try:
            payload = self.unsign(signed_payload)
        except BadSignature:
            # Signature is invalid, try to deserialize the payload.
            try:
                data = self.load_payload(signed_payload)  # type: ignore[arg-type]
                return False, data
            except BadPayload:
                return False, None
        else:
            data = self.load_payload(payload)
            return True, data

