def style(text, **styles):
    """Return a string with ANSI style codes applied."""
    if not styles:
        return text

    codes = []
    if "fg" in styles:
        fg = styles["fg"]
        if isinstance(fg, (list, tuple)):
            codes.append(f"38;2;{';'.join(map(str, fg))}")
        else:
            codes.append(_color_to_code(fg, foreground=True))

    if "bg" in styles:
        bg = styles["bg"]
        if isinstance(bg, (list, tuple)):
            codes.append(f"48;2;{';'.join(map(str, bg))}")
        else:
            codes.append(_color_to_code(bg, foreground=False))

    if "bold" in styles and styles["bold"]:
        codes.append("1")
    if "dim" in styles and styles["dim"]:
        codes.append("2")
    if "underline" in styles and styles["underline"]:
        codes.append("4")
    if "blink" in styles and styles["blink"]:
        codes.append("5")
