def _get_completions(
    ctx: Context,
    param: Parameter,
    incomplete: str,
) -> t.Iterator[CompletionItem]:
    # If the parameter has a default and the user hasn't typed anything yet,
    # include the default value as a possible completion.
    if not incomplete and param.default is not None:
        yield CompletionItem(param.default)
    # If the parameter has a type that provides completions, use them.
    if isinstance(param.type, Choice):
        for choice in param.type.choices:
            if choice.startswith(incomplete):
                yield CompletionItem(choice)
    # Fallback to no completions.
    return
